---@class CommonMarqueeNode
local CommonMarqueeNode = Class('CommonMarqueeNode')
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


function CommonMarqueeNode:__init()
	self.txtWidth = 0
	self.maskWidth = 0  --最大的x移动范围   目前按中心anchors和中心pivot计算
	self.moveSpeed = 30
	self.offsetY = 0
	self.maxX = 0
	
	self.stopTime = 0 --移动到最大距离后的停留时间
	self.timer = self.stopTime
end

---@private
function CommonMarqueeNode:RefreshParams()
	self.txtWidth = self.TxtDesc.rect.width * self.TxtDesc.localScale.x
	self.maskWidth = self.MaskText.rect.width
	if self.maskWidth > self.txtWidth then
		self.maxX = 0
	else
		self.maxX = self.maskWidth * 0.5 + self.txtWidth * 0.5
	end
	
	self.offsetY = self.TxtDesc.anchoredPosition.y
end

function CommonMarqueeNode:__delete()

end

function CommonMarqueeNode:Awake()

end

function CommonMarqueeNode:Start()
	self:RefreshParams()
	self._behaviourAction = KTool.GetOrAddComponent(self.MaskText.gameObject, typeof(BehaviourAction))
	if self._behaviourAction then
		self._behaviourAction.UpdateAction = function()
			self:Update()
		end
	end
end

function CommonMarqueeNode:Update()
	if self.maxX > 0 then
		if self.timer > 0 then
			self.timer = self.timer - CS.UnityEngine.Time.deltaTime
			return
		end
		
		local newX = self.TxtDesc.transform.anchoredPosition.x - (CS.UnityEngine.Time.deltaTime * self.moveSpeed)
		if math.abs(newX) >= self.maxX then
			self.timer = self.stopTime
			self.TxtDesc.transform.anchoredPosition = Vector3(self.maxX, self.offsetY, 0)
		else
			self.TxtDesc.transform.anchoredPosition = Vector3(newX, self.offsetY, 0)
		end
	else
		if self.isRefresh then
			self:RefreshParams()
		end
	end
end

function CommonMarqueeNode:Refresh(str)
	self.isRefresh = true
	local offsetY = self.TxtDesc.anchoredPosition.y
	self.TxtDesc.transform.anchoredPosition = Vector3(0, offsetY, 0)
	CfUtils.FillText(self.TxtDesc, checkString(str))
	CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.TxtDesc)
	self:RefreshParams()
end

function CommonMarqueeNode:OnDestroy()
	if not isNull(self._behaviourAction) then
		self._behaviourAction.UpdateAction = nil
	end
	
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
	self = nil
end

return CommonMarqueeNode